    from PIL import Image

    t = t.detach().to("cpu", copy = True).float()

    k = 3
    mu, sigma = t.mean(), t.std()
    lo, hi = mu - k * sigma, mu + k * sigma
    t.clamp_(lo, hi)
    t -= lo
    t /= (hi - lo + 1e-8)

    rgba = cm.get_cmap("gnuplot2")(t.numpy())
    rgb8 = (rgba[..., :3] * 255).astype("uint8")
